ALTER TABLE feasibility_extracted_texts ADD COLUMN image_count INTEGER NOT NULL DEFAULT 0;
CREATE TABLE feasibility_extracted_images (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, job_id TEXT NOT NULL REFERENCES account_jobs(id) ON DELETE CASCADE, source_key TEXT NOT NULL, content_hash TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL, object_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(job_id,source_key,content_hash));
